SetStatus("Self");int _rg=(int)(5*Self.dynamicVariables.GetValueOrDefault("ReturnAgainGainMultiplier",1f));
        if(_rg>0){AddBuff(DataId.buff_ReturnAgain,_rg.ToString());}
        var pool=new List<string>{DataId.ReturnAgain_1,DataId.ReturnAgain_3,DataId.ReturnAgain_4,DataId.ReturnAgain_5,DataId.ReturnAgain_6,DataId.ReturnAgain_7,DataId.ReturnAgain_8,DataId.ReturnAgain_9,DataId.ReturnAgain_10,DataId.ReturnAgain_11,DataId.ReturnAgain_12,DataId.ReturnAgain_13,DataId.ReturnAgain_14,DataId.ReturnAgain_15};
        if(pool.Count>0)
        {int idx=DefaultDice.WithRange(0,pool.Count-1).Roll().Value;
        CreateCard(new DataConfig(pool[idx],DataType.Card));}

