Variables.UseScript:
if (!PlayerInfo.SkillTime.ContainsKey(DataId.careercard_4))
        {
            PlayerInfo.SkillTime[DataId.careercard_4] = 0;
        }
        PlayerInfo.SkillTime[DataId.careercard_4] +=12;
       if (PlayerInfo.SpecialVars==null)
        {
            return;
        }
        DataConfig temp;
        int count=int.Parse(PlayerInfo.SpecialVars.GetValueOrDefault("Soul","0"));
        if (count<100)
        {
            temp = new(DataId.nocard_1, DataType.Card);
        }
        else if (count<200)
        {
            temp = new(DataId.nocard_2, DataType.Card);
        }
        else
        {
            temp = new(DataId.nocard_3, DataType.Card);
        }
        var tempList=new List<CardItem>(HandCard);
        PlayerInfo.UpdateAch("achievement_adela_obsidian_legion",tempList.Count);
        foreach (var item in tempList)
        {
            item.TransformToConfiguredType(temp);
        }

